import { Db } from '@cloudbase/database'
import { ICloudbase } from '@cloudbase/types'
import { ICloudbaseComponent } from '@cloudbase/types/component'
import cloudbaseNS from '../../index'
import { EJSON } from 'bson'
import { constants, utils } from '@cloudbase/utilities'

declare const cloudbase: ICloudbase
declare type QueryType = 'WHERE' | 'DOC'

/**
 * 数据库配置接口
 */
interface IDbConfig {
  /** 实例 ID（可选，默认 '(default)'） */
  instance?: string
  /** 数据库名称（可选，默认 '(default)'） */
  database?: string
}

interface IBaseReq extends IDbConfig {
  collectionName: string
  transactionId?: string
}

interface IDocumentsQueryReq extends IBaseReq {
  query?: any
  /** @deprecated 使用 query 替代 */
  queryType?: QueryType
  /** 排序规则：引擎传 {field: -1|1} 或其 EJSON 字符串，网关要求 [{field, direction}]，adapter 内统一转换 */
  order?: Record<string, any> | { field: string; direction: string }[] | string
  offset?: number
  limit?: number
  projection?: Object
}

interface IDocumentsAddReq extends IBaseReq {
  data: Object | Object[]
}

interface IDocumentsUpdateReq extends IBaseReq {
  query: Object
  data: Object
  /** 是否批量更新（默认 false） */
  multi?: boolean
  /** 把所有更新数据转为带操作符的 */
  merge?: boolean
  /** 不存在时是否创建（默认 false） */
  upsert?: boolean
  /** 是否替换整个文档（默认 false，为 true 时替换整个文档而非合并更新） */
  replaceMode?: boolean
  /** @deprecated 使用 query 替代 */
  queryType?: QueryType
}

interface IDocumentsRemoveReq extends IBaseReq {
  query: Object
  /** 是否批量删除（默认 false） */
  multi?: boolean
  /** @deprecated 使用 query 替代 */
  queryType?: QueryType
}

interface IDocumentsCountReq extends IBaseReq {
  query: Object
  /** @deprecated 使用 query 替代 */
  queryType?: QueryType
}

interface ICommonRes<T> {
  data?: T & { code?: string }
  requestId: string
  code?: string
  message?: string
}

interface IAddRes {
  /** 单条插入时返回的文档 ID（批量插入时不返回） */
  _id?: string
  /** 批量插入时返回的文档 ID 列表 */
  ids?: string[]
  insertedIds: string[]
}

interface IRunCommandsReq {
  transactionId?: string
  /** 命令数组，方法会将其转为 MongoDB 原生命令（EJSON 对象格式） */
  commands: Object[]
}

const COMPONENT_NAME = 'database'

// 导出以便单测直测各 handler / 工具函数（运行时逻辑不依赖导出）
export const gateWayFunc = {
  /**
   * 过滤响应，移除不必要的字段，并统一把 data.code/data.message 提升到顶层。
   *
   * Node 端 fetch 不按 HTTP 状态抛错：非 2xx 也 resolve，body 经 safeParseJson
   * 留下（502 纯文本/HTML 是字符串，500 空 JSON 是 {} 或 null），只靠 statusCode 区分。
   * 这里随后会删掉 statusCode，而事务提交等调用方只看 res.code。
   * 因此 HTTP >= 400 且没有业务 code 时补 NETWORK_ERROR，避免把提交失败当成成功。
   */
  filterRes <T>(res: ICommonRes<T> & { header?: any; statusCode?: number }): ICommonRes<T> {
    res = utils.promoteGatewayError(res)
    const status = Number(res.statusCode)
    if (status >= 400 && !res.code) {
      const body: unknown = res.data
      const text = typeof body === 'string' && body.trim() ? body.slice(0, 1024) : ''
      res.code = constants.ERRORS.NETWORK_ERROR
      res.message = text || res.message || `HTTP ${status}`
    }
    delete res.header
    delete res.statusCode
    return res
  },

  /**
   * 展开响应数据到顶层（用于事务等场景）
   */
  flattenResData <T>(res: ICommonRes<T>): any {
    if (typeof res.data === 'object' && res.data !== null) {
      const result = { ...res, ...res.data }
      delete result.data
      return result
    }
    return res
  },

  /**
   * 安全解析 EJSON
   */
  safeParseEJSON(data: any): any {
    if (typeof data !== 'string') return data
    try {
      return EJSON.parse(data)
    } catch {
      return data
    }
  },

  /**
   * 解析 2.0 引擎的 EJSON 字符串参数为纯 JSON 对象。
   *
   * 2.0 引擎的 query/data 等参数为 EJSON.stringify 产出的合法 JSON 字符串，
   * 直接 JSON.parse 即可让 $numberInt/$date/$regularExpression 等类型标记
   * 以纯对象形式保留（注意不能用 EJSON.parse——它会还原成 JS 值/实例，
   * 后续 JSON.stringify 会丢失类型标记）。
   *
   * 实测网关契约（RESTful）：
   * - 入参 body：v2 严格模式（$numberInt/$numberDouble/$date/$numberLong）均支持；
   *   $regularExpression 写入返回 400（写入侧由 parseWriteParam 转 v1 兼容）
   * - 入参 URL query：v1/v2 均支持（含正则查询）
   * - 响应：一律严格模式（v2 编码），由上层 EJSON.parse 还原
   */
  parseEJSONParam(value: any): any {
    if (typeof value !== 'string') return value
    try {
      return JSON.parse(value)
    } catch {
      return value
    }
  },

  /**
   * EJSON 字符串解析为普通 JS 值（$numberInt/$numberLong 等标记还原为真实数字）。
   * 用于 order/projection 等网关只接受纯 JSON 数值的参数。
   * 注意：query 走 parseEJSONParam（保留类型标记，v2 网关查询方向支持），两者方向相反。
   */
  parseEJSONValue(value: any): any {
    if (typeof value !== 'string') return value
    try {
      return EJSON.parse(value)
    } catch {
      return gateWayFunc.parseEJSONParam(value)
    }
  },

  /**
   * 把排序参数统一转为网关要求的 [{field, direction}] 格式。
   *
   * 1.x 引擎 orderBy 生成 {field: -1|1}（经 EJSON 序列化后数字带 $numberInt
   * 标记），网关不认这种格式（报 Invalid order format）。无法识别的输入
   * 返回 undefined（即不发 order 参数）。
   */
  normalizeOrderParam(value: any): any {
    if (value === undefined || value === null || value === '') return undefined

    const order = gateWayFunc.parseEJSONValue(value)

    const toDirection = (v: any): string | undefined => {
      // EJSON.parse 后数字可能是 Int32/Long 实例，Number() 还原为原始值
      const n = v && typeof v === 'object' ? Number(v) : v
      if (typeof n === 'number' && !isNaN(n)) return n < 0 ? 'desc' : 'asc'
      if (typeof n === 'string') {
        const s = n.toLowerCase()
        if (s === 'desc' || s === '-1') return 'desc'
        if (s === 'asc' || s === '1') return 'asc'
      }
      return undefined
    }

    const items = Array.isArray(order) ? order : [order]
    const ret: { field: string; direction: string }[] = []
    for (const item of items) {
      if (!item || typeof item !== 'object') continue
      if (item.field !== undefined) {
        // 已是网关格式 [{field, direction}]
        const direction = toDirection(item.direction)
        if (direction) ret.push({ field: item.field, direction })
      } else {
        // 引擎格式 {field: -1|1}，可能多字段
        for (const [field, dir] of Object.entries(item)) {
          const direction = toDirection(dir)
          if (direction) ret.push({ field, direction })
        }
      }
    }
    return ret.length ? ret : undefined
  },

  /**
   * 从查询条件中提取单文档 ID（无法提取时返回 undefined）。
   *
   * 仅当 query 为单一 _id 等值条件时生效（键数必须为 1，避免
   * where({_id: 'x', status: 1}) 这类复合条件误判）。兼容以下形式：
   * - {_id: 'xxx'}（引擎 doc.get/update/set/remove 的实际形态，queryType: 'DOC'）
   * - {_id: {$eq: 'xxx'}}
   * - {_id: {$oid: 'xxx'}}（EJSON 序列化后的 ObjectId）
   * - {_id: {$eq: {$oid: 'xxx'}}}
   */
  extractDocId(query: any): string | undefined {
    if (!query || typeof query !== 'object' || Array.isArray(query)) return undefined
    if (Object.keys(query).length !== 1 || !('_id' in query)) return undefined

    const id = query._id
    if (typeof id === 'string' || typeof id === 'number') return String(id)
    if (id && typeof id === 'object') {
      if (typeof id.$oid === 'string') return id.$oid
      const eq = id.$eq
      if (typeof eq === 'string' || typeof eq === 'number') return String(eq)
      if (eq && typeof eq === 'object' && typeof eq.$oid === 'string') return eq.$oid
    }
    return undefined
  },

  /**
   * 递归把 v2 的 $regularExpression 转为 v1 的 {$regex, $options}。
   *
   * 仅用于写入/更新的文档数据（data）：实测网关 body 不接受 $regularExpression（400），
   * 而 v1 的 {$regex, $options} 可正常写入。查询条件（query）方向 v1/v2 均支持，
   * 不做转换。
   */
  toLegacyRegExp(value: any): any {
    if (!value || typeof value !== 'object') return value
    if (value.$regularExpression && typeof value.$regularExpression === 'object') {
      const { pattern, options } = value.$regularExpression
      return { $regex: pattern, $options: options }
    }
    if (Array.isArray(value)) {
      return value.map(item => gateWayFunc.toLegacyRegExp(item))
    }
    const ret: any = {}
    for (const key in value) {
      ret[key] = gateWayFunc.toLegacyRegExp(value[key])
    }
    return ret
  },

  /**
   * 解析写入类参数（文档数据）：JSON.parse 保留类型标记后，
   * 仅把 v2 正则转 v1——只用于 insert 路径（实测网关 POST 写入只认 v1 正则；
   * PATCH 更新路径相反，只认 v2，见 modifyDocument 注释）
   */
  parseWriteParam(value: any): any {
    return gateWayFunc.toLegacyRegExp(gateWayFunc.parseEJSONParam(value))
  },

  /**
   * 构建 URL 查询参数
   */
  buildQueryParams(params: Record<string, any>): string {
    return Object.entries(params)
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      .filter(([_, value]) => value !== undefined && value !== null && value !== '')
      .map(([key, value]) => {
        const stringValue = typeof value === 'object' ? JSON.stringify(value) : String(value)
        return `${encodeURIComponent(key)}=${encodeURIComponent(stringValue)}`
      })
      .join('&')
  },

  /**
   * 获取 URL 前缀
   */
  getUrlPrefix(data: IDbConfig): string {
    const instance = data?.instance || '(default)'
    const database = data?.database || '(default)'
    return `/database/instances/${instance}/databases/${database}`
  },

  async 'database.queryDocument'(data: IDocumentsQueryReq, customReqOpts?: any,): Promise<ICommonRes<{ offset?: number; limit?: number; list: any[] }>> {
    // 入参归一化：兼容对象与 EJSON 字符串两种形态（历史引擎/旧事务路径可能传字符串），
    // parseEJSONParam 对对象原样返回，对字符串 JSON.parse 保留类型标记
    const query = gateWayFunc.parseEJSONParam(data.query)
    const projection = gateWayFunc.parseEJSONValue(data.projection)

    // 单文档查询：{_id: 值} / {_id: {$eq}} / {_id: {$oid}} 等单一 _id 等值条件
    // （引擎 doc.get() 发 queryType:'DOC' + query={"_id":"xxx"}），
    // 走专用端点 GET /documents/:docId，网关会自动兼容 ObjectId 字符串主键
    const docId = gateWayFunc.extractDocId(query)
    const isQueryDoc = docId !== undefined
    const queryParams = gateWayFunc.buildQueryParams({
      projection,
      transactionId: data.transactionId,
      ...(isQueryDoc
        ? {}
        : {
          offset: data.offset ?? 0,
          limit: data.limit ?? 100,
          order: gateWayFunc.normalizeOrderParam(data.order),
          query: query ? EJSON.stringify(query, { relaxed: false }) : undefined,
        }),
    })

    let url = `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents?${queryParams}`

    // 查询单个文档
    if (isQueryDoc) {
      url = `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents/${docId}?${queryParams}`
    }

    let res = await this.gateWay({
      url,
      method: 'GET',
    }, customReqOpts)

    // 尝试解析 EJSON 格式的数据
    res.data = gateWayFunc.safeParseEJSON(JSON.stringify(res.data))

    if (isQueryDoc && !res.code && !res.data?.code) {
      return {
        ...res,
        data: { list: [res.data] }
      }
    }

    // 确保 res.data.list 为数组，兼容后端返回数据或直接返回文档数组的情况
    if (!res.code && !res.data?.code) {
      if (Array.isArray(res.data)) {
        // 后端直接返回文档数组
        res = { ...res, data: { list: res.data } }
      } else if (res.data && !Array.isArray(res.data.list)) {
        // 后端返回对象但缺少 list 字段
        res = { ...res, data: { ...res.data, list: [] } }
      }
    } else {
      res = { ...res, data: { ...res.data, list: [] } }
    }

    return gateWayFunc.filterRes(res)
  },

  async 'database.addDocument'(data: IDocumentsAddReq, customReqOpts?: any): Promise<ICommonRes<IAddRes>> {
    // 入参归一化：条目可能是对象或 EJSON 字符串（直调方/历史引擎），
    // 统一 parseWriteParam（JSON.parse 保留标记 + 写入口径正则转 v1）；
    // 对已是对象的条目幂等
    const items = (Array.isArray(data.data) ? data.data : [data.data])
      .map(item => gateWayFunc.parseWriteParam(item))

    let res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents`,
      method: 'POST',
      data: {
        data: items,
        ...(data.transactionId && { transactionId: data.transactionId }),
      },
    }, customReqOpts)

    if (Array.isArray(data.data)) {
      // 数组模式（批量插入），返回 ids 列表
      res = {
        ...res,
        data: {
          ids: res.data?.insertedIds || [],
          ...res.data,
        },
      }
    } else if (res.data?.insertedIds?.[0]) {
      // 非数组模式（单条插入），将 _id 提升到顶层
      res = {
        ...res,
        data: {
          _id: res.data.insertedIds[0],
          ...res.data,
        },
      }
    }

    return gateWayFunc.filterRes(res)
  },

  async 'database.updateDocument'(data: IDocumentsUpdateReq, customReqOpts?: any,): Promise<ICommonRes<{ matched: number; updated: number; upsert_id: string }>> {
    // 入参归一化：query/data 兼容对象与 EJSON 字符串（对象原样返回，幂等）
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents`,
      method: 'PATCH',
      data: {
        query: gateWayFunc.parseEJSONParam(data.query),
        data: gateWayFunc.parseEJSONParam(data.data),
        multi: !!data.multi,
        upsert: !!data.upsert,
        replaceMode: data.replaceMode ?? data.merge === false,
        ...(data.transactionId && { transactionId: data.transactionId }),
      },
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.deleteDocument'(data: IDocumentsRemoveReq, customReqOpts?: any): Promise<ICommonRes<{ deleted: number }>> {
    // 入参归一化：query 兼容对象与 EJSON 字符串
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents/remove`,
      method: 'POST',
      data: {
        query: gateWayFunc.parseEJSONParam(data.query),
        multi: !!data.multi,
        ...(data.transactionId && { transactionId: data.transactionId }),
      },
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.countDocument'(data: IDocumentsCountReq, customReqOpts?: any): Promise<ICommonRes<{ total: number }>> {
    // 入参归一化：query 兼容对象与 EJSON 字符串
    const query = gateWayFunc.parseEJSONParam(data.query)
    const queryParams = gateWayFunc.buildQueryParams({
      count: true,
      query: query ? EJSON.stringify(query, { relaxed: false }) : undefined,
    })

    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents?${queryParams}`,
      method: 'GET',
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.addCollection'(data: { collectionName: string } & IDbConfig, customReqOpts?: any): Promise<ICommonRes<''>> {
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections`,
      method: 'POST',
      data: { collectionName: data.collectionName },
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.aggregate'(data: { collectionName: string; stages: { stageKey: string; stageValue: any }[] } & IDbConfig, customReqOpts?: any,): Promise<ICommonRes<{ list: string }>> {
    const pipeline = data.stages.map((stage) => {
      try {
        // stageValue 可能是字符串或对象，统一处理
        const value = typeof stage.stageValue === 'string' ? JSON.parse(stage.stageValue) : stage.stageValue
        return {
          [stage.stageKey]: EJSON.serialize(value),
        }
      } catch {
        return { [stage.stageKey]: stage.stageValue }
      }
    })

    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/collections/${data.collectionName}/documents/aggregations`,
      method: 'POST',
      data: { pipeline },
    }, customReqOpts)

    // 将结果列表转为字符串格式（兼容原有逻辑）
    if (Array.isArray(res.data?.list)) {
      res.data.list = JSON.stringify(res.data.list.map((item: any) => JSON.stringify(item)))
    }

    return gateWayFunc.filterRes(res)
  },

  async 'database.startTransaction'(data: IDbConfig, customReqOpts?: any) {
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/transactions`,
      method: 'POST',
    }, customReqOpts)

    return gateWayFunc.filterRes(gateWayFunc.flattenResData(res))
  },

  async 'database.commitTransaction'(data: { transactionId: string } & IDbConfig, customReqOpts?: any) {
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/transactions/${data.transactionId}/commit`,
      method: 'POST',
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.abortTransaction'(data: { transactionId: string } & IDbConfig, customReqOpts?: any) {
    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/transactions/${data.transactionId}/rollback`,
      method: 'POST',
    }, customReqOpts)

    return gateWayFunc.filterRes(res)
  },

  async 'database.getInTransaction'(data: IDocumentsQueryReq, customReqOpts?: any) {
    const res = await gateWayFunc['database.queryDocument'].call(this, data, customReqOpts)

    if (typeof res.data === 'object' && res.data !== null) {
      if (res.data?.code) {
        return gateWayFunc.flattenResData(res)
      }
      return { ...res, data: JSON.stringify(res.data) as any }
    }

    return res
  },

  async 'database.updateDocInTransaction'(data: IDocumentsUpdateReq, customReqOpts?: any) {
    // query/data 可能是 EJSON 字符串（历史引擎），由 updateDocument 内部统一归一化
    const res = await gateWayFunc['database.updateDocument'].call(this, data, customReqOpts)
    return gateWayFunc.flattenResData(res)
  },

  async 'database.deleteDocInTransaction'(data: IDocumentsRemoveReq, customReqOpts?: any) {
    // query 可能是 EJSON 字符串，由 deleteDocument 内部统一归一化
    const res = await gateWayFunc['database.deleteDocument'].call(this, data, customReqOpts)
    return gateWayFunc.flattenResData(res)
  },

  async 'database.insertDocInTransaction'(data: IDocumentsAddReq, customReqOpts?: any,): Promise<ICommonRes<IAddRes & { inserted?: number }>> {
    // data 条目可能是对象或 EJSON 字符串，由 addDocument 内部统一 parseWriteParam
    let res = await gateWayFunc['database.addDocument'].call(this, data, customReqOpts)

    if (typeof res.data === 'object' && res.data !== null) {
      const hasId = !!res.data?._id
      res = {
        ...res,
        inserted: hasId ? 1 : 0,
        ok: hasId ? 1 : 0,
        ...res.data,
      } as any
    } else {
      res = { inserted: 0, ok: 0, ...res } as any
    }

    delete res.data

    return res
  },

  async 'database.runCommands'(data: IRunCommandsReq & IDbConfig, customReqOpts?: any,): Promise<ICommonRes<{ list: Object[][] }>> {
    let res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(data)}/commands`,
      method: 'POST',
      data: {
        // 命令条目兼容对象与 EJSON 字符串，序列化保留类型标记
        commands: EJSON.serialize(
          Array.isArray(data.commands)
            ? data.commands.map(cmd => gateWayFunc.parseEJSONParam(cmd))
            : data.commands
        ),
        ...(data.transactionId && { transactionId: data.transactionId }),
      },
    }, customReqOpts)

    if (typeof res.data === 'object' && res.data !== null) {
      res = { ...res, ...res.data }
      delete res.data
      delete res.request_id
    }

    // 尝试将结果转换为普通对象
    try {
      res = EJSON.deserialize(res)
    } catch {
      // 忽略转换失败
    }

    return gateWayFunc.filterRes(res)
  },

  // ===================== 2.0 引擎新接口名映射 =====================
  // @cloudbase/database 2.0 引擎使用新接口名（getDocument/insertDocument/...），
  // 且 query/data 等参数为 EJSON 字符串格式。这里统一适配后委托给上面的
  // 旧接口实现，保证 GATEWAY 模式下新旧引擎都能正确路由到 RESTful 网关。

  async 'database.getDocument'(data: IDocumentsQueryReq, customReqOpts?: any): Promise<ICommonRes<{ offset?: number; limit?: number; list: any[] }>> {
    // 2.0 引擎的 query/order/projection 为 EJSON 字符串。
    // query 解析后保留类型标记（v2 网关查询方向支持）；
    // projection 用 EJSON 解析还原真实数字（JSON.parse 会保留 $numberInt
    // 标记，网关只认 {"name":1} 这种纯 JSON 数值）；
    // order 在 queryDocument 内由 normalizeOrderParam 统一转为网关格式
    const normalized: any = { ...data }
    normalized.query = gateWayFunc.parseEJSONParam(normalized.query)
    normalized.projection = gateWayFunc.parseEJSONValue(normalized.projection)

    const res = await gateWayFunc['database.queryDocument'].call(this, normalized, customReqOpts)

    // 2.0 引擎期望 data.list 为 EJSON 字符串数组。
    // 注意：旧实现已将响应 EJSON.parse 成 JS 值（Date/BSONRegExp 等实例），
    // 必须用 EJSON.stringify 序列化以保留类型标记（JSON.stringify 会把
    // BSONRegExp 剥成裸 pattern/options、Date 转成 ISO 字符串，造成类型丢失）
    if (Array.isArray(res.data?.list)) {
      res.data.list = res.data.list.map((item: any) => EJSON.stringify(item, { relaxed: false }))
    }
    return res
  },

  async 'database.insertDocument'(data: IDocumentsAddReq, customReqOpts?: any): Promise<ICommonRes<IAddRes>> {
    // 2.0 引擎的 data 为 EJSON 字符串数组；
    // 写入口径：仅把 v2 正则转 v1（$regex/$options），其余类型标记保持 v2
    const normalized: any = { ...data }
    normalized.data = Array.isArray(normalized.data)
      ? normalized.data.map((item: any) => gateWayFunc.parseWriteParam(item))
      : gateWayFunc.parseWriteParam(normalized.data)

    return gateWayFunc['database.addDocument'].call(this, normalized, customReqOpts)
  },

  async 'database.modifyDocument'(data: IDocumentsUpdateReq, customReqOpts?: any): Promise<ICommonRes<{ matched: number; updated: number; upsert_id: string }>> {
    const normalized: any = { ...data }
    // query 为查询条件：v1/v2 网关均支持，保持 v2 不转
    // data 为写入内容：同样保持 v2——实测网关 PATCH（更新）路径只认 v2 正则
    // （v1 的 $regex/$options 会被 MongoDB 当 $ 前缀字段拒绝存储），
    // 与 insert 路径（只认 v1）相反
    normalized.query = gateWayFunc.parseEJSONParam(normalized.query)
    normalized.data = gateWayFunc.parseEJSONParam(normalized.data)

    return gateWayFunc['database.updateDocument'].call(this, normalized, customReqOpts)
  },

  async 'database.modifyAndReturnDoc'(data: IDocumentsUpdateReq, customReqOpts?: any): Promise<any> {
    // 引擎 query.updateAndReturn() 调用。网关仅在单文档端点
    // PATCH /documents/:docId 上支持 returnDoc:true（响应含更新后文档），
    // query 为 _id 等值时走单文档端点；否则降级为批量更新（无 doc 返回，
    // 引擎侧对 res.data.doc 有判空守卫）。
    const normalized: any = { ...data }
    normalized.query = gateWayFunc.parseEJSONParam(normalized.query)
    normalized.data = gateWayFunc.parseEJSONParam(normalized.data)

    const docId = gateWayFunc.extractDocId(normalized.query)
    if (!docId) {
      return gateWayFunc['database.updateDocument'].call(this, normalized, customReqOpts)
    }

    const res = await this.gateWay({
      url: `${gateWayFunc.getUrlPrefix(normalized)}/collections/${normalized.collectionName}/documents/${docId}`,
      method: 'PATCH',
      data: {
        data: normalized.data,
        replaceMode: normalized.replaceMode ?? false,
        upsert: !!normalized.upsert,
        returnDoc: true,
        ...(normalized.transactionId && { transactionId: normalized.transactionId }),
      },
    }, customReqOpts)

    // 引擎期望 doc 为 EJSON 字符串（EJSON.parse(res.data.doc) 还原类型）
    if (res.data?.doc !== undefined && typeof res.data.doc !== 'string') {
      res.data.doc = EJSON.stringify(res.data.doc, { relaxed: false })
    }

    return gateWayFunc.filterRes(res)
  },

  async 'database.removeDocument'(data: IDocumentsRemoveReq, customReqOpts?: any): Promise<ICommonRes<{ deleted: number }>> {
    const normalized: any = { ...data }
    normalized.query = gateWayFunc.parseEJSONParam(normalized.query)

    // 仅针对 collection.remove()（不带 where）恢复 v3 全表删除语义：
    // 引擎 Query._fieldFilters 默认为空字符串 ''（CollectionReference 构造传入），
    // GATEWAY 网关要求 query 必须为非空对象，空 query 会报 INVALID_PARAM。
    // 兜底为恒真条件 {_id: {$exists: true}}（已实测网关接受，等价删除全部文档）。
    // 影响面严格限定：where(...).remove() 的 query 非空不触发；
    // 事务 doc 删除走 deleteDocInTransaction（必带 _id）不经过本处理器；
    // where({}) 的空对象属于用户显式调用，语义交由服务端，不做兜底。
    if (normalized.query === undefined || normalized.query === null || normalized.query === '') {
      normalized.query = { _id: { $exists: true } }
    }

    return gateWayFunc['database.deleteDocument'].call(this, normalized, customReqOpts)
  },

  async 'database.calculateDocument'(data: IDocumentsCountReq, customReqOpts?: any): Promise<ICommonRes<{ total: number }>> {
    const normalized: any = { ...data }
    normalized.query = gateWayFunc.parseEJSONParam(normalized.query)

    return gateWayFunc['database.countDocument'].call(this, normalized, customReqOpts)
  },

  async 'database.aggregateDocuments'(data: { collectionName: string; stages: { stageKey: string; stageValue: any }[] } & IDbConfig, customReqOpts?: any,): Promise<ICommonRes<{ list: any }>> {
    // stages 为查询语义（match 等），v2 标记保持原样
    const normalized: any = { ...data }
    if (Array.isArray(normalized.stages)) {
      normalized.stages = normalized.stages.map((stage: any) => ({
        ...stage,
        stageValue: gateWayFunc.parseEJSONParam(stage.stageValue)
      }))
    }
    const res = await gateWayFunc['database.aggregate'].call(this, normalized, customReqOpts)

    // 旧实现把 list 转成 JSON 大字符串（0.12.x 兼容格式），
    // 2.0 引擎期望 list 为字符串数组，还原之
    if (typeof res.data?.list === 'string') {
      try {
        res.data.list = JSON.parse(res.data.list)
      } catch {
        // 解析失败保持原样
      }
    }
    return res
  },
}

function database(dbConfig?: IDbConfig) {
  // 对齐 v3 node-sdk newDb 的参数校验：dbConfig 必须是普通对象，
  // undefined 视为默认空配置；string/array/null 等类型抛 INVALID_PARAM（同步）。
  if (
    dbConfig !== undefined
    && Object.prototype.toString.call(dbConfig).slice(8, -1) !== 'Object'
  ) {
    throw utils.createCloudbaseError({
      code: 'INVALID_PARAM',
      msg: 'dbConfig must be an object',
    }, (this.config as any)?.errorFactory)
  }

  const { adapter, runtime } = this.platform

  class Req extends this.request.constructor {
    constructor(config) {
      super(config)
    }

    async send(action: string, data: any, opts?: { timeout?: number }) {
      let res = null

      // 2.0 引擎的第三个参数为 getReqOpts（目前仅含 per-request timeout），
      // 转换为基础请求类的 customReqOpts 透传到底层 fetch（AbortController 超时）
      const customReqOpts
        = opts && typeof opts.timeout === 'number' ? { timeout: opts.timeout } : undefined

      if (this.config.endPointMode === 'GATEWAY' && gateWayFunc[action]) {
        res = await gateWayFunc[action].call(this, data, customReqOpts)
      } else {
        res = await super.send(action, data, undefined, customReqOpts)
      }

      // 统一 throw 开关（默认 true）：抛原始业务码（DATABASE_COLLECTION_NOT_EXIST 等）；
      // throw=false 时返回 {code,message,requestId} 让调用方用 if (res.code) 检查。
      // 优先读实例 config（_fromApp.config.throw，per-instance 且支持运行时 setThrowOnCode 联动），
      // 因为 this.config 是 database() 时的快照（{...config} 展开），不会随 setThrowOnCode 更新。
      const shouldThrow = utils.resolveThrow((this.config as any)?._fromApp?.config ?? this.config)
      if (res && res.code && shouldThrow) {
        throw utils.createCloudbaseError({
          code: res.code,
          msg: res.message || (res.data && res.data.message) || '',
          requestId: res.requestId,
        }, (this.config as any)?.errorFactory)
      }

      return res
    }
  }

  Db.reqClass = Req
  // 未登录情况下传入空函数
  Db.getAccessToken = this.authInstance ? this.authInstance.getAccessToken.bind(this.authInstance) : () => ''
  Db.runtime = runtime
  if (this.wsClientClass) {
    Db.wsClass = adapter.wsClass
    Db.wsClientClass = this.wsClientClass
  }

  if (!Db.ws) {
    Db.ws = null
  }

  class NewDb extends Db {
    constructor(config?: IDbConfig) {
      super(config)
    }

    async runCommands(params: IRunCommandsReq): Promise<ICommonRes<{ list: Object[][] }>> {
      const request = Db.createRequest(this.config)

      return request.send('database.runCommands', params)
    }
  }

  return new NewDb({ ...this.config, _fromApp: this, ...dbConfig })
}

const component: ICloudbaseComponent = {
  name: COMPONENT_NAME,
  entity: {
    database,
  },
}
try {
  cloudbase.registerComponent(component)
} catch (e) {}

export function registerDatabase(app: ICloudbase | typeof cloudbaseNS) {
  try {
    app.registerComponent(component)
  } catch (e) {
    console.warn(e)
  }
}

try {
  (window as any).registerDatabase = registerDatabase
} catch (e) {}
